    import ansible.plugins.action.validate_argument_spec as mod

    class _FakeTemplar:
        def __init__(self, lookup_vars):
            self._lookup_vars = lookup_vars

        def template(self, data):
            if isinstance(data, dict):
                return {k: self.template(v) for k, v in data.items()}
            if isinstance(data, str) and data.startswith('{{') and data.endswith('}}'):
                key = data[2:-2].strip()
                return self._lookup_vars[key]
            return data

    class _FakeTask:
        args = {}

    action = mod.ActionModule(
        task=_FakeTask(),
        connection=None,
        play_context=None,
        loader=None,
        templar=None,
        shared_loader_obj=None,
    )
    action._templar = _FakeTemplar({'web_host': 'server1.example.com'})

    argument_spec = {
        'name': {'type': 'str'},
        'port': {'type': 'int'},
    }
    task_vars = {
        'name': '{{ web_host }}',
        'port': 8080,
        'unrelated_var': 'should_not_be_collected',
    }

    args = action.get_args_from_task_vars(argument_spec, task_vars)

    assert args == {'name': 'server1.example.com', 'port': 8080}, args
